mapper.select:
select id, batch_no, plan_date, factory, glue,glue_name,sap_code, mix_area, total_plan_qty, mid_plan_qty, mid_remark,
night_plan_qty, night_remark, day_plan_qty, day_remark, data_source, remark, del_flag, create_by, create_time,
update_by, update_time from t_glue_demand_plan
where del_flag = '0'
and batch_no = #{batchNo}
and plan_date = #{planDate}
and factory = #{factory}
and INSTR(glue, #{glue}) > 0
and INSTR(mix_area, #{mixArea}) >0
and data_source = #{dataSource}

    order by (case when instr(mix_area,',') > 0 then '0' when mix_area is null or mix_area = '' then '0' else mix_area end)/*多个密炼区 和 没有密炼区的排在前面*/


    order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, concat_ws('', #{data.planDate} , #{data.factory} , #{data.glue} , #{data.mixArea}) uniqueKey FROM dual
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_glue_demand_plan m inner join temp_table t on concat_ws('', m.plan_date , m.factory, m.glue , m.mixArea ) = t.uniqueKey and m.del_flag ='0'

mapper.insert:
insert into t_glue_demand_plan
(id,batch_no,plan_date,factory,glue,glue_name,sap_code,mix_area,total_plan_qty,mid_plan_qty,mid_remark,night_plan_qty,night_remark,day_plan_qty,day_remark,data_source,remark,del_flag,create_by,create_time,update_by,update_time
)
select NULL id, x.*
from (

    select
    #{glueDemandPlan.batchNo,jdbcType= VARCHAR} batch_no, #{glueDemandPlan.planDate,jdbcType=DATE} plan_date,
    #{glueDemandPlan.factory,jdbcType= VARCHAR} factory, #{glueDemandPlan.glue,jdbcType= VARCHAR} glue,
    #{glueDemandPlan.glueName,jdbcType= VARCHAR} glue_name,#{glueDemandPlan.sapCode,jdbcType= VARCHAR} sap_code,
    #{glueDemandPlan.mixArea,jdbcType= VARCHAR} mix_area, #{glueDemandPlan.totalPlanQty,jdbcType=DOUBLE}
    total_plan_qty, #{glueDemandPlan.midPlanQty,jdbcType=DOUBLE} mid_plan_qty,
    #{glueDemandPlan.midRemark,jdbcType= VARCHAR} mid_remark, #{glueDemandPlan.nightPlanQty,jdbcType=DOUBLE}
    night_plan_qty, #{glueDemandPlan.nightRemark,jdbcType= VARCHAR} night_remark,
    #{glueDemandPlan.dayPlanQty,jdbcType=DOUBLE} day_plan_qty, #{glueDemandPlan.dayRemark,jdbcType= VARCHAR}
    day_remark, #{glueDemandPlan.dataSource,jdbcType= VARCHAR} data_source,
    #{glueDemandPlan.remark,jdbcType= VARCHAR} remark, #{glueDemandPlan.delFlag,jdbcType= VARCHAR} del_flag,
    #{glueDemandPlan.createBy,jdbcType= VARCHAR} create_by, #{glueDemandPlan.createTime,jdbcType=DATE}
    create_time, #{glueDemandPlan.updateBy,jdbcType= VARCHAR} update_by,
    #{glueDemandPlan.updateTime,jdbcType=DATE} update_time from dual

) x
